// Automated Sales Report Generator: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const rows = input.map(r => ({ ...r, d: new Date(r.date + 'T00:00:00'), rev: Number(r.qty) * Number(r.unit_price) }));
const end = new Date(Math.max(...rows.map(r => r.d))), start = new Date(end - 6 * 864e5), prevStart = new Date(start - 7 * 864e5);
const cur = rows.filter(r => r.d >= start && r.d <= end), prev = rows.filter(r => r.d >= prevStart && r.d < start);
const k = rs => { const rev = rs.reduce((s, r) => s + r.rev, 0), orders = new Set(rs.map(r => r.order_id)).size; return { rev, orders, aov: orders ? rev / orders : 0 }; };
const by = (rs, key) => rs.reduce((o, r) => (o[r[key]] = (o[r[key]] || 0) + r.rev, o), {});
const pct = (a, b) => b ? ((a - b) / b * 100).toFixed(1) + '%' : 'n/a';
const k1 = k(cur), k0 = k(prev), p1 = by(cur, 'product'), p0 = by(prev, 'product');
const movers = [...new Set([...Object.keys(p1), ...Object.keys(p0)])].map(p => [p, (p1[p] || 0) - (p0[p] || 0)]).sort((a, b) => b[1] - a[1]);
const branches = Object.entries(by(cur, 'branch')).sort((a, b) => b[1] - a[1]);
const f = n => 'NGN ' + Math.round(n).toLocaleString();
const report = [`Week ${start.toISOString().slice(0, 10)} to ${end.toISOString().slice(0, 10)}`,
  `Revenue ${f(k1.rev)} (${pct(k1.rev, k0.rev)} vs last week)`, `Orders ${k1.orders} (${pct(k1.orders, k0.orders)})`,
  `Average order ${f(k1.aov)} (${pct(k1.aov, k0.aov)})`, `Biggest gain: ${movers[0][0]} (+${f(movers[0][1])})`,
  `Biggest drop: ${movers[movers.length - 1][0]} (${f(movers[movers.length - 1][1])})`, `Top branch: ${branches[0][0]} with ${f(branches[0][1])}`].join('\n');
return [{ json: { revenue: k1.rev, change: pct(k1.rev, k0.rev), report } }];
